import { elements, molecularMass, CLASS_NA, format } from './core.js';
export function foundationLesson(){
 const water=molecularMass('H2O'),carbon=molecularMass('CO2');
 return '<section class="foundation-lesson" aria-labelledby="foundation-title" data-glossary-skip><div class="lesson-section-heading"><span class="eyebrow">從這裡開始 / 三個基礎觀念</span><h3 id="foundation-title">先知道「多重」，再學會「有多少」</h3><p>原子組成分子；莫耳幫我們把看不見的微粒，連到天平上的克數。</p></div><div class="foundation-grid"><article><span class="concept-index">01 / 比較一種原子</span><h4>原子量</h4><div class="atom-mass-tokens"><span><b>H</b><small>氫</small><strong>'+elements.H.ar+'</strong></span><span><b>C</b><small>碳</small><strong>'+elements.C.ar+'</strong></span><span><b>O</b><small>氧</small><strong>'+elements.O.ar+'</strong></span></div><p>把<b>一個碳-12 原子質量的 1/12</b>當作比較標準。元素原子的平均質量除以這個標準，就是相對原子量。</p><p class="concept-key">它是比值，沒有單位。<br>氧的原子量 16，並不是一顆氧原子重 16 g。</p></article><article><span class="concept-index">02 / 加總一個分子</span><h4>分子量</h4><div class="water-molecule" aria-label="一個水分子由兩個氫原子與一個氧原子組成"><i>H</i><b>O</b><i>H</i></div><p>分子由原子組成，把一個分子中所有原子的原子量加總起來，就是分子量。</p><div class="concept-formula">H₂O：2 × 1 + 16 = <b>'+water+'</b></div><p class="concept-key">分子量也沒有單位。<br>CO₂：12 + 2 × 16 = '+carbon+'。</p></article><article><span class="concept-index">03 / 數一大群微粒</span><h4>莫耳 <small>mol</small></h4><div class="carbon-scale-comparison" role="group" aria-label="一顆碳原子與一莫耳碳原子的比較"><figure><svg viewBox="0 0 180 145" role="img" aria-label="一顆碳-12 原子的放大球形示意"><defs><radialGradient id="carbon-single-shade" cx=".3" cy=".25" r=".8"><stop stop-color="#a5b9b0"/><stop offset=".4" stop-color="#4e6961"/><stop offset="1" stop-color="#1b3530"/></radialGradient></defs><ellipse cx="90" cy="119" rx="40" ry="7" fill="#274d3a" opacity=".1"/><circle cx="90" cy="70" r="43" fill="none" stroke="#c4d1bc" stroke-dasharray="3 5"/><circle cx="90" cy="70" r="33" fill="url(#carbon-single-shade)" stroke="#456358"/><ellipse cx="79" cy="54" rx="13" ry="7" fill="#e3eee5" opacity=".17"/><text x="90" y="80" text-anchor="middle" fill="#fffdf0" font-family="Georgia,serif" font-size="30">C</text></svg><figcaption><b>一顆碳原子</b><strong>1 <small>顆</small></strong><span>約 1.99 × 10<sup>−23</sup> g</span><small>單顆原子・放大示意</small></figcaption></figure><figure><svg viewBox="0 0 180 145" role="img" aria-label="一莫耳碳-12 原子組成的一份碳樣品，天平顯示約 12 公克"><defs><linearGradient id="carbon-scale-metal" x2="0" y2="1"><stop stop-color="#fbfcf4"/><stop offset="1" stop-color="#b4c7b8"/></linearGradient><linearGradient id="carbon-sample-shade" x2=".8" y2="1"><stop stop-color="#6d8079"/><stop offset="1" stop-color="#283e37"/></linearGradient></defs><ellipse cx="90" cy="130" rx="64" ry="6" fill="#274d3a" opacity=".12"/><path d="M33 94H147L157 127H23Z" fill="url(#carbon-scale-metal)" stroke="#9bafa0"/><rect x="30" y="90" width="120" height="8" rx="4" fill="#d5e1d2" stroke="#9caf9b"/><ellipse cx="90" cy="89" rx="48" ry="8" fill="#8fa797" opacity=".4"/><path d="M43 81Q90 106 137 81" fill="#fdfdf5" stroke="#a5b6a2"/><ellipse cx="90" cy="81" rx="47" ry="8" fill="#f9faf2" stroke="#a5b6a2"/><path d="M56 79L64 64 80 59 85 47 105 51 113 64 124 77 108 84 78 86Z" fill="url(#carbon-sample-shade)" stroke="#3f564c"/><path d="M64 64L86 70 85 47M86 70L105 51M86 70L78 86M86 70L113 64M86 70L108 84" fill="none" stroke="#9eafa3" stroke-width="1" opacity=".5"/><rect x="61" y="103" width="60" height="18" rx="3" fill="#254c3c"/><text x="91" y="116" text-anchor="middle" fill="#eef5d6" font-family="monospace" font-size="12">12.00 g</text></svg><figcaption><b>一莫耳碳原子</b><strong>6.02 × 10<sup>23</sup> <small>顆</small></strong><span>約 12 g</span><small>一份碳樣品・實物示意</small></figcaption></figure></div><p class="carbon-scale-note">本圖以<b>碳-12</b>為例，粒子數與質量取近似值；兩圖不按相同比例繪製。<br><b>1 mol 是一大群原子，不是一顆變大的原子。</b></p><p>就像一打有 12 個，莫耳是物質的量的單位。說「1 mol」時，要指出數的是<b>原子、分子或離子</b>。</p><p class="concept-key">1 mol 水與 1 mol 二氧化碳：<br>分子個數相同，質量不同。</p></article></div><section class="atomic-mole-bridge" aria-labelledby="atomic-mole-title"><div class="lesson-section-heading"><span class="eyebrow">把原子量與莫耳接起來</span><h3 id="atomic-mole-title">原子量告訴我們：一莫耳這種原子約有幾克</h3><p>原子量本身沒有單位；換成一莫耳原子的質量時，數值約相同，單位變成公克。本章使用近似值。</p></div><div class="atomic-mole-examples"><div><span class="mole-element">C</span><div><b>碳原子</b><span>原子量 12</span></div><i aria-hidden="true">→</i><p>1 mol 碳原子<strong>約 12 <small>g</small></strong></p></div><div><span class="mole-element">H</span><div><b>氫原子</b><span>原子量 1</span></div><i aria-hidden="true">→</i><p>1 mol 氫原子<strong>約 1 <small>g</small></strong></p></div></div><div class="atomic-mole-check" role="group" aria-labelledby="atomic-mole-question"><span class="eyebrow">換你想想 / 點選答案</span><h4 id="atomic-mole-question">氧原子的原子量是 16，那麼 1 mol 氧原子約有幾克？</h4><div class="atomic-mole-options"><button type="button" data-atomic-mass="1" aria-pressed="false">1 g</button><button type="button" data-atomic-mass="16" aria-pressed="false">16 g</button><button type="button" data-atomic-mass="32" aria-pressed="false">32 g</button></div><p class="atomic-mole-feedback" role="status" aria-live="polite">跟著碳、氫的例子，找出原子量與一莫耳質量的關係。</p></div><details class="molecular-mole-extension"><summary>再延伸：換成水分子，也是同樣的道理嗎？</summary><p>水 H₂O 的分子量是 18，所以 1 mol 水分子的質量約是 18 g。</p><p><b>例：36 g 水 ÷ 18 g/mol＝2 mol 水分子。</b></p></details></section><p class="foundation-footnote">本章使用教學近似值；1 mol 的精確定義為 6.02214076 × 10²³ 個指定粒子。NaCl 等離子化合物沒有獨立分子，依化學式加總的相對質量稱為「式量」。 <a href="https://www.bipm.org/en/si-base-units/mole" target="_blank" rel="noopener">莫耳定義 ↗</a> · <a href="https://www.nist.gov/pml/special-publication-811/nist-guide-si-chapter-8" target="_blank" rel="noopener">相對質量定義 ↗</a></p></section>';
}
export function equationLesson(){return '<section class="equation-primer" data-glossary-skip><div class="lesson-section-heading"><span class="eyebrow">先看示範，再動手配平</span><h3>寫化學反應式的四個步驟</h3></div><ol class="equation-writing"><li><b>確認反應物與生成物</b><p>氫氣和氧氣反應，生成水。先認識物質，不能為了湊數隨意猜化學式。</p></li><li><b>左邊寫反應物，右邊寫生成物</b><p class="concept-formula">H₂ + O₂ → H₂O <small>（尚未配平）</small></p></li><li><b>只改係數，讓各種原子一樣多</b><p class="concept-formula"><em>2</em>H₂ + O₂ → <em>2</em>H₂O</p><p>左右各有 4 個 H、2 個 O。係數 1 省略；H₂O 的下標不能改。</p></li><li><b>標出狀態與需要的條件</b><p>(s) 固體、(l) 液體、(g) 氣體、(aq) 水溶液。加熱、點火或催化劑等條件寫在箭頭旁，依實際反應填寫。</p></li></ol><div class="equation-note"><b>係數比 2：1：2</b><span>表示氫氣、氧氣、水的分子數比或莫耳數比；不是質量比。</span></div></section>';}

export function mountFoundationCheck(root){
 const buttons=root.querySelectorAll('[data-atomic-mass]'),feedback=root.querySelector('.atomic-mole-feedback');
 buttons.forEach(button=>button.addEventListener('click',()=>{
  const answer=Number(button.dataset.atomicMass);
  buttons.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
  feedback.dataset.correct=String(answer===16);
  feedback.textContent=answer===16?'✓ 答對了！氧的原子量是 16，所以 1 mol 氧原子的質量約是 16 g。注意：1 mol 氧氣分子 O₂ 含 2 mol 氧原子，質量才約是 32 g。':answer===32?'你選的 32 g 是 1 mol 氧氣分子 O₂ 的質量。題目問的是氧原子 O，請再想一次。':'1 g 對應的是 1 mol 氫原子。氧的原子量是 16，請對照上方例子再選一次。';
 }));
 return {reset(){buttons.forEach(button=>button.setAttribute('aria-pressed','false'));delete feedback.dataset.correct;feedback.textContent='跟著碳、氫的例子，找出原子量與一莫耳質量的關係。';}};
}